window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5f7c2effce13e67c"]={"versions": [{"id": "FIG-5f7c2effce13e67c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-Metamodells zur Spezifikation des Basic Software Module Description Template (BSWMDT), Unterbereich BSW Exclusive Areas. Dargestellt ist die strukturelle Verankerung von Exklusivbereichen (<code>ExclusiveArea</code>) und deren Schachtelungsregeln (<code>ExclusiveAreaNestingOrder</code>) in generischen Verhaltensbeschreibungen (<code>InternalBehavior</code>) sowie deren Spezialisierung für BSW-Verhaltensbeschreibungen (<code>BswInternalBehavior</code>) und ausführbare Einheiten (<code>BswModuleEntity</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (spezialisiert <code>AtpStructureElement</code>): Aggregiert per Komposition über die Rolle <code>exclusiveArea</code> (Kardinalität <code>0..<em></code>, Stereotyp <code>«atpVariation»</code>) Instanzen von <code>ExclusiveArea</code> sowie über <code>exclusiveAreaNestingOrder</code> (Kardinalität <code>0..</em></code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen von <code>ExclusiveAreaNestingOrder</code>.</li>\n<li><code>BswInternalBehavior</code>: Spezialisiert <code>InternalBehavior</code>. Aggregiert per Komposition über die Rolle <code>entity</code> (Kardinalität <code>1..*</code>, Stereotyp <code>«atpVariation»</code>) Instanzen der abstrakten Klasse <code>BswModuleEntity</code>.</li>\n<li><code>ExclusiveArea</code> (spezialisiert <code>Identifiable</code>): Repräsentiert den kritischen Bereich zur Unterdrückung von Vorab-Unterbrechungen (Preemption).</li>\n<li><code>ExclusiveAreaNestingOrder</code> (spezialisiert <code>Referrable</code>): Besitzt eine geordnete Referenzliste <code>exclusiveArea</code> (<code>0..*</code>, <code>{ordered}</code>) auf <code>ExclusiveArea</code>.</li>\n<li><code>ExecutableEntity</code> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse. Referenziert Exklusivbereiche über <code>canEnterExclusiveArea</code> (<code>0..<em></code>) und <code>runsInsideExclusiveArea</code> (<code>0..</em></code>) und verweist über <code>exclusiveAreaNestingOrder</code> (<code>0..*</code>) auf zulässige Schachtelungsordnungen.</li>\n<li><code>BswModuleEntity</code>: Spezialisiert <code>ExecutableEntity</code>. Aggregiert per Komposition über <code>callPoint</code> (<code>0..*</code>, Stereotyp <code>«atpVariation»</code>) Aufrufpunkte vom Typ <code>BswModuleCallPoint</code>.</li>\n<li><code>BswModuleCallPoint</code> (spezialisiert <code>Referrable</code>): Abstrakte Basisklasse für Aufrufpunkte.</li>\n<li><code>BswDirectCallPoint</code> und <code>BswSynchronousServerCallPoint</code>: Spezialisieren <code>BswModuleCallPoint</code>. Beide besitzen eine optionale Assoziation <code>calledFromWithinExclusiveArea</code> (Kardinalität <code>0..1</code>) zu <code>ExclusiveArea</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Dynamisch relevante Aspekte werden deklarativ modelliert:</p>\n<ul class=\"fig-list\">\n<li>Eintrittsberechtigungen (<code>canEnterExclusiveArea</code>) bzw. die vollständige Ausführung innerhalb eines kritischen Bereichs (<code>runsInsideExclusiveArea</code>) legen Laufzeitbeschränkungen für <code>ExecutableEntity</code> fest.</li>\n<li>Die Ausführung von synchronen Serveraufrufen (<code>BswSynchronousServerCallPoint</code>) oder direkten Aufrufen (<code>BswDirectCallPoint</code>) innerhalb eines Exklusivbereichs wird über <code>calledFromWithinExclusiveArea</code> deklariert, um Sperrzeiten zu analysieren.</li>\n<li>Schachtelungen mehrerer Exklusivbereiche müssen der durch <code>ExclusiveAreaNestingOrder</code> definierten Sequenz folgen, um Deadlocks zur Laufzeit zu vermeiden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Modellierungsregeln: Die Kompositionen <code>exclusiveAreaNestingOrder</code> (<code>InternalBehavior</code>) unterstützen Variabilitäts- und Splitting-Mechanismen (<code>«atpVariation,atpSplitable»</code>), während <code>exclusiveArea</code> und <code>entity</code> ausschließlich variabilitätsfähig (<code>«atpVariation»</code>) sind.</li>\n<li>Konsistenz und Deadlock-Prävention: Werden innerhalb einer <code>BswModuleEntity</code> mehrere <code>ExclusiveArea</code>-Instanzen geschachtelt betreten, muss eine kompatible <code>ExclusiveAreaNestingOrder</code> deklariert sein.</li>\n<li>Schachtelungstiefe und Call-Points: Aufrufe externer Schnittstellen aus einem Exklusivbereich heraus (<code>calledFromWithinExclusiveArea</code>) verlängern die Blockierzeiten und unterliegen Beschränkungen der AUTOSAR BSW-Architektur.</li>\n</ul>"}, {"id": "FIG-51589b1847f87946", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-Metamodells zur Spezifikation des Basic Software Module Description Template (BSWMDT), Unterbereich BSW Exclusive Areas. Dargestellt ist die strukturelle Verankerung von Exklusivbereichen (<code>ExclusiveArea</code>) und deren Schachtelungsregeln (<code>ExclusiveAreaNestingOrder</code>) in generischen Verhaltensbeschreibungen (<code>InternalBehavior</code>) sowie deren Spezialisierung für BSW-Verhaltensbeschreibungen (<code>BswInternalBehavior</code>) und ausführbare Einheiten (<code>BswModuleEntity</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (spezialisiert <code>AtpStructureElement</code>): Aggregiert per Komposition über die Rolle <code>exclusiveArea</code> (Kardinalität <code>0..<em></code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen von <code>ExclusiveArea</code> sowie über <code>exclusiveAreaNestingOrder</code> (Kardinalität <code>0..</em></code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen von <code>ExclusiveAreaNestingOrder</code>.</li>\n<li><code>BswInternalBehavior</code>: Spezialisiert <code>InternalBehavior</code>. Aggregiert per Komposition über die Rolle <code>entity</code> (Kardinalität <code>1..*</code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen der abstrakten Klasse <code>BswModuleEntity</code>.</li>\n<li><code>ExclusiveArea</code> (spezialisiert <code>Identifiable</code>): Repräsentiert den kritischen Bereich zur Unterdrückung von Vorab-Unterbrechungen (Preemption).</li>\n<li><code>ExclusiveAreaNestingOrder</code> (spezialisiert <code>Referrable</code>): Besitzt eine geordnete Referenzliste <code>exclusiveArea</code> (<code>0..*</code>, <code>{ordered}</code>) auf <code>ExclusiveArea</code>.</li>\n<li><code>ExecutableEntity</code> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse. Referenziert Exklusivbereiche über <code>canEnterExclusiveArea</code> (<code>0..<em></code>) und <code>runsInsideExclusiveArea</code> (<code>0..</em></code>) und verweist über <code>exclusiveAreaNestingOrder</code> (<code>0..*</code>) auf zulässige Schachtelungsordnungen.</li>\n<li><code>BswModuleEntity</code>: Spezialisiert <code>ExecutableEntity</code>. Aggregiert per Komposition über <code>callPoint</code> (<code>0..*</code>, Stereotyp <code>«atpVariation»</code>) Aufrufpunkte vom Typ <code>BswModuleCallPoint</code>.</li>\n<li><code>BswModuleCallPoint</code> (spezialisiert <code>Referrable</code>): Abstrakte Basisklasse für Aufrufpunkte.</li>\n<li><code>BswDirectCallPoint</code> und <code>BswSynchronousServerCallPoint</code>: Spezialisieren <code>BswModuleCallPoint</code>. Beide besitzen eine optionale Assoziation <code>calledFromWithinExclusiveArea</code> (Kardinalität <code>0..1</code>) zu <code>ExclusiveArea</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Dynamisch relevante Aspekte werden deklarativ modelliert:</p>\n<ul class=\"fig-list\">\n<li>Eintrittsberechtigungen (<code>canEnterExclusiveArea</code>) bzw. die vollständige Ausführung innerhalb eines kritischen Bereichs (<code>runsInsideExclusiveArea</code>) legen Laufzeitbeschränkungen für <code>ExecutableEntity</code> fest.</li>\n<li>Die Ausführung von synchronen Serveraufrufen (<code>BswSynchronousServerCallPoint</code>) oder direkten Aufrufen (<code>BswDirectCallPoint</code>) innerhalb eines Exklusivbereichs wird über <code>calledFromWithinExclusiveArea</code> deklariert, um Sperrzeiten zu analysieren.</li>\n<li>Schachtelungen mehrerer Exklusivbereiche müssen der durch <code>ExclusiveAreaNestingOrder</code> definierten Sequenz folgen, um Deadlocks zur Laufzeit zu vermeiden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Modellierungsregeln: Die Kompositionen <code>exclusiveAreaNestingOrder</code>, <code>exclusiveArea</code> (aus <code>InternalBehavior</code>) sowie <code>entity</code> (aus <code>BswInternalBehavior</code>) unterstützen Variabilitäts- und Splitting-Mechanismen (<code>«atpVariation,atpSplitable»</code>).</li>\n<li>Konsistenz und Deadlock-Prävention: Werden innerhalb einer <code>BswModuleEntity</code> mehrere <code>ExclusiveArea</code>-Instanzen geschachtelt betreten, muss eine kompatible <code>ExclusiveAreaNestingOrder</code> deklariert sein.</li>\n<li>Schachtelungstiefe und Call-Points: Aufrufe externer Schnittstellen aus einem Exklusivbereich heraus (<code>calledFromWithinExclusiveArea</code>) verlängern die Blockierzeiten und unterliegen Beschränkungen der AUTOSAR BSW-Architektur.</li>\n</ul>"}], "trans": [{"from": "FIG-5f7c2effce13e67c", "to": "FIG-51589b1847f87946", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>InternalBehavior.exclusiveArea</strong>: Stereotyp von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.</li>\n<li><strong>BswInternalBehavior.entity</strong>: Stereotyp von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.</li>\n</ul>"}]};
